CREATE TEMP TABLE s503c_cards (id bigint, s_ed text, s_book text, src_ch int, src_vn int, src_text text, t_ed text, tgt_book text, tgt_ch int, tgt_vn int, old_note text, new_note text, thread_id bigint, old_mnote text, new_mnote text) ON COMMIT DROP;
INSERT INTO s503c_cards VALUES
(2917,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','matthew',25,40,$n$*Inasmuch as ye have done it unto one of the least of these my brethren* — FRAMEWORK-MAJOR criterion.$n$,$n$Matthew 25:40 — *And the King shall answer and say unto them, Verily I say unto you, Inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me.* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) Here is what the sifting weighs. Yahusha (Jesus) names the measure himself, and it is mercy shown to *the least of these my brethren*. The sheep are the gathered who showed that mercy to the least of the seed while all of them were out among the nations, and what was done to them he counts as done to him.$n$,18,$n$*Inasmuch as ye have done it unto one of the least of these my brethren* — FRAMEWORK-MAJOR criterion.$n$,$n$Matthew 25:40 — *Inasmuch as ye have done it unto one of the least of these my brethren.* The measure at the throne is mercy shown to his brethren, and he takes it as shown to himself.$n$),
(2918,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','matthew',25,46,$n$The substantial-everlasting-punishment vs life-eternal substance.$n$,$n$Matthew 25:46 — *And these shall go away into everlasting punishment: but the righteous into life eternal.* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) The parting ends in two roads. Those on the left go away into *everlasting punishment*, and the righteous go into *life eternal*. The sifting at the throne is what sends each group on, the goats divided from the sheep among the gathered.$n$,18,$n$The substantial-everlasting-punishment vs life-eternal substance.$n$,$n$Matthew 25:46 — *these shall go away into everlasting punishment.* The two ends of the parting: the goats go to punishment and the righteous go into life.$n$),
(2919,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','matthew',19,28,$n$*The Son of Adam shall sit in the throne of his glory.*$n$,$n$Matthew 19:28 — *And Yahusha (Jesus) said unto them, Verily I say unto you, That ye which have followed me, in the regeneration when the Son of Adam shall sit in the throne of his glory, ye also shall sit upon twelve thrones, judging the twelve tribes of Yashar'el (Israel).* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) Yahusha (Jesus) says it to Peter ahead of time. The Son of Adam sits on the throne of his glory, and those who followed him sit on twelve thrones over *the twelve tribes of Yashar'el (Israel)*. The ones before the throne are that bloodline people, the scattered seed being gathered and sorted.$n$,18,$n$The King-substance shall-sit-on-the-throne-of-his-glory + the twelve-thrones.$n$,$n$Matthew 19:28 — *judging the twelve tribes of Yashar'el (Israel).* The throne of his glory stands over the twelve tribes of Yashar'el (Israel), the people gathered and sifted there.$n$),
(2920,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','matthew',24,30,$n$The Son-of-Adam-coming-in-the-clouds + the gathering.$n$,$n$Matthew 24:30 — *And then shall appear the sign of the Son of Adam in heaven: and then shall all the tribes of the earth mourn, and they shall see the Son of Adam coming in the clouds of heaven with power and great glory.* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) The same coming, seen from the other side. The sign of the Son of Adam shows in heaven, and *all the tribes of the earth mourn*. Just after this his angels gather the elect from the four winds. That gathering is what fills the place before the throne.$n$,18,$n$The Son-of-Adam-coming-in-the-clouds + the gathering-of-the-elect.$n$,$n$Matthew 24:30 — *they shall see the Son of Adam coming in the clouds of heaven.* The coming in the clouds is the same coming, with the tribes gathered to it from the four winds.$n$),
(2921,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','matthew',12,46,$n$The King's-brethren = those-who-do-the-will-of-the-Father.$n$,$n$Matthew 12:46 — *While he yet talked to the people, behold, his mother and his brethren stood without, desiring to speak with him.* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) His mother and *his brethren* stand outside while he speaks to the people, and he asks who his brethren are. The question is answered at the throne. The brethren he names there are the seed he came for, the lost sheep of the house of Yashar'el (Israel), the ones who do the will of his Father.$n$,18,$n$The King's-brethren = those-who-do-the-will-of-the-Father.$n$,$n$Matthew 12:46 — *While he yet talked to the people, behold, his mother and his brethren stood without.* The question of who his brethren are is first raised here, and the throne gives the answer.$n$),
(2922,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','ezekiel',34,11,$n$The substantial-shepherd-substance + the judgment-between-cattle-and-cattle.$n$,$n$Ezekiel 34:11 — *For thus saith Adonai Yahuah (the Lord GOD); Behold, I, even I, will both search my sheep, and seek them out.* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) The shepherd who divides sheep from goats at the throne is the one Ezekiel heard say *will both search my sheep*. He seeks them first, out of every place they were scattered, and only then sorts them. The sifting is the shepherd's own work on his own flock.$n$,18,$n$The substantial-shepherd-substance + the judgment-between-cattle-and-cattle.$n$,$n$Ezekiel 34:11 — *I, even I, will both search my sheep, and seek them out.* The shepherd himself goes looking for his scattered sheep before he sorts them.$n$),
(2923,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','ezekiel',34,17,$n$*I judge between cattle and cattle.*$n$,$n$Ezekiel 34:17 — *And as for you, O my flock, thus saith Adonai Yahuah (the Lord GOD); Behold, I judge between cattle and cattle, between the rams and the he goats.* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) Ezekiel has the same sorting, and it falls inside the flock. He speaks to *my flock* and judges *between cattle and cattle*. The goats are among the sheep when he divides them. So the parting is among the gathered, the way the throne shows it, and not a trial of outsiders.$n$,18,$n$*I judge between cattle and cattle, between the rams and the he goats* — direct anchor for sheep-and-goats.$n$,$n$Ezekiel 34:17 — *I judge between cattle and cattle, between the rams and the he goats.* The parting of rams from he goats is made within the flock, which is how the throne divides the gathered.$n$),
(2926,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','isaiah',66,18,$n$*I will gather all nations and tongues* + the priestly-relationship-substance.$n$,$n$Isaiah 66:18 — *For I know their works and their thoughts: it shall come, that I will gather all nations and tongues; and they shall come, and see my glory.* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) Before the throne stand *all nations*, and Isaiah says why. He gathers them, and they come and *see my glory*. Two verses on it is your brethren who are brought out of all nations to his holy mountain. So all nations is where the gathered are called out of, the field the seed was scattered in.$n$,18,$n$*I will gather all nations and tongues* + the priestly-relationship-substance.$n$,$n$Isaiah 66:18 — *I will gather all nations and tongues; and they shall come, and see my glory.* The gathering out of all nations and tongues is the gathering the throne scene starts from.$n$),
(2927,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','daniel',7,13,$n$The Son-of-Adam-substance per Red Line #12.$n$,$n$Daniel 7:13 — *I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) Daniel saw *one like the Son of Adam* come with the clouds and be brought near before the Ancient of days. That is the coming Yahusha (Jesus) names. The next verse gives him dominion and a kingdom, so the one who sits to sort the gathered is the one given the kingdom.$n$,18,$n$The Son-of-Adam-substance + dominion + kingdom-given.$n$,$n$Daniel 7:13 — *one like the Son of Adam came with the clouds of heaven.* Daniel's one like the Son of Adam coming with the clouds is the one who takes the throne.$n$),
(2928,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','daniel',12,2,$n$Some-to-everlasting-life + some-to-shame-and-everlasting-contempt.$n$,$n$Daniel 12:2 — *And many of them that sleep in the dust of the earth shall awake, some to everlasting life, and some to shame and everlasting contempt.* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) Daniel sees the same parting of one people into two ends. Some wake *to everlasting life*, and some *to shame and everlasting contempt*. The verse before speaks of his people, every one found written in the book. So this too is a division among the gathered, as with the sheep and goats.$n$,18,$n$Some-to-everlasting-life + some-to-shame-and-everlasting-contempt.$n$,$n$Daniel 12:2 — *some to everlasting life, and some to shame and everlasting contempt.* One people parts into two ends, life for some and shame for others, as at the throne.$n$),
(2929,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','isaiah',66,24,$n$The substantial-everlasting-fire-substance.$n$,$n$Isaiah 66:24 — *And they shall go forth, and look upon the carcases of the men that have transgressed against me: for their worm shall not die, neither shall their fire be quenched; and they shall be an abhorring unto all flesh.* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) The fire on the left hand is Isaiah's fire. Those who go forth look on *the carcases of the men that have transgressed*, and *neither shall their fire be quenched*. A little before it, the seed and its name remain. The seed stays, and the transgressors among them do not.$n$,18,$n$The substantial-everlasting-fire-substance.$n$,$n$Isaiah 66:24 — *for their worm shall not die, neither shall their fire be quenched.* The unquenched fire falls on the transgressors while the seed remains.$n$),
(2930,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','hebrews',2,11,$n$The King calls-the-seed-of-Avraham-substance his-brethren.$n$,$n$Hebrews 2:11 — *For both he that sanctifieth and they who are sanctified are all of one: for which cause he is not ashamed to call them brethren,* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) Here is who the brethren are. The one who sanctifies and the ones sanctified are *all of one*, and he is not ashamed to call them brethren. The verses after bring in the children Elohim (God) gave him. His brethren are the sanctified seed who share his Father, not a people made up from the nations.$n$,18,$n$The King calls-the-seed-of-Avraham-substance his-brethren.$n$,$n$Hebrews 2:11 — *for which cause he is not ashamed to call them brethren.* He calls the sanctified seed his brethren, and they are the ones the throne counts mercy toward.$n$),
(2931,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','romans',8,29,$n$*The firstborn among many brethren.*$n$,$n$Romans 8:29 — *For whom he did foreknow, he also did predestinate to be conformed to the image of his Son, that he might be the firstborn among many brethren.* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) The many brethren have a firstborn. Those he calls his own at the throne are the ones Paul says were foreknown and made like the image of his Son, with Yahusha (Jesus) the eldest among them. The family is known before the sifting, and the sifting shows who is in it.$n$,18,$n$*The firstborn among many brethren.*$n$,$n$Romans 8:29 — *he might be the firstborn among many brethren.* The brethren are a family with the Son as firstborn, known before the sifting begins.$n$),
(2932,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','john',20,17,$n$*Go to my brethren* — the King's-own-mouth identification.$n$,$n$John 20:17 — *Yahusha (Jesus) saith unto her, Touch me not; for I am not yet ascended to my Father: but go to my brethren, and say unto them, I ascend unto my Father, and your Father; and to my Elohim (God), and your Elohim (God).* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) Yahusha (Jesus) himself says who his brethren are. To Mary, the first witness at the tomb, he says *go to my brethren*, and she carries the word to the disciples. He speaks of *my Father, and your Father*, so his brethren share his Father. The throne's brethren are these.$n$,18,$n$*Go to my brethren* — the King's-own-mouth identification.$n$,$n$John 20:17 — *go to my brethren, and say unto them, I ascend unto my Father, and your Father.* In his own words the brethren are those who share his Father, and Mary is sent to them.$n$),
(2933,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','matthew',28,10,$n$*Go tell my brethren* — post-resurrection identification.$n$,$n$Matthew 28:10 — *Then said Yahusha (Jesus) unto them, Be not afraid: go tell my brethren that they go into Galilee, and there shall they see me.* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) The women who came to the tomb are sent as witnesses with the word *my brethren*. He gives that name to his own and sends them to Galilee, where they will see him. The name at the throne belongs to the same people, the scattered flock he has come to gather.$n$,18,$n$*Go tell my brethren* — post-resurrection identification.$n$,$n$Matthew 28:10 — *go tell my brethren that they go into Galilee, and there shall they see me.* After the tomb he again calls his own his brethren, the same name the throne uses.$n$),
(2934,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','acts',9,4,$n$*Why persecutest thou me?* — the King identifies with his brethren.$n$,$n$Acts 9:4 — *And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me?* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) What is done to his own is done to him. Saul was dragging men and women bound to Jerusalem, and the voice asks *why persecutest thou me*. It is the same weighing as the throne, where mercy or its lack toward the least of his brethren is counted as done to him.$n$,18,$n$*Why persecutest thou me?* — the King identifies with his brethren.$n$,$n$Acts 9:4 — *heard a voice saying unto him, Saul, Saul, why persecutest thou me.* Harm done to his people is taken as done to him, the same weighing the throne makes.$n$),
(2938,'canon','matthew',25,31,$n$When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:$n$,'canon','revelation',5,10,$n$The kingdom-priests reigning-on-the-earth.$n$,$n$Revelation 5:10 — *And hast made us unto our Elohim (God) kings and priests: and we shall reign on the earth.* *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* (Matthew 25:31) The sheep take the kingdom, and this is what they are in it. They are made *kings and priests* and reign on the earth. They are redeemed *out of every kindred, and tongue, and people, and nation* (Revelation 5:9). They are gathered out first and then set over the nations as priests.$n$,18,$n$The kingdom-priests reigning-on-the-earth.$n$,$n$Revelation 5:10 — *hast made us unto our Elohim (God) kings and priests: and we shall reign on the earth.* The sheep who inherit the kingdom reign on the earth as kings and priests.$n$),
(5073,'canon','mark',6,11,$n$And whosoever shall not receive you, nor hear you, when you depart thence, shake off the dust under your feet for a testimony against them. Verily I say unto you, It shall be more tolerable for Sodom and Gomorrah in the day of judgment, than for that city.$n$,'canon','matthew',11,23,$n$thread:sheep-and-goats-judgment-of-the-nations-at-the-throne-of-his-glory | *It shall be more tolerable for Sodom and Gomorrah in the day of judgment, than for that city.* The day-of-judgment threshold lands the consequence on the city that refused the messengers.$n$,$n$Matthew 11:23 — *And thou, Capernaum, which art exalted unto heaven, shalt be brought down to hell: for if the mighty works, which have been done in thee, had been done in Sodom, it would have remained until this day.* *And whosoever shall not receive you, nor hear you, when you depart thence, shake off the dust under your feet for a testimony against them. Verily I say unto you, It shall be more tolerable for Sodom and Gomorrah in the day of judgment, than for that city.* (Mark 6:11) Capernaum was a city of Yashar'el (Israel), and it saw the mighty works. Yahusha (Jesus) says they would have remained in Sodom had they been done there. The city that heard and refused is judged harder than Sodom. The judgment lands first on those given the most to hear, among his own people.$n$,18,$n$*It shall be more tolerable for Sodom and Gomorrah in the day of judgment, than for that city.* The day-of-judgment threshold lands the consequence on the city that refused the messengers.$n$,$n$Matthew 11:23 — *the mighty works, which have been done in thee, had been done in Sodom.* The city that saw the works and refused is held worse than Sodom, so judgment starts among his own.$n$),
(5074,'canon','mark',6,11,$n$And whosoever shall not receive you, nor hear you, when you depart thence, shake off the dust under your feet for a testimony against them. Verily I say unto you, It shall be more tolerable for Sodom and Gomorrah in the day of judgment, than for that city.$n$,'canon','2-peter',2,6,$n$thread:sheep-and-goats-judgment-of-the-nations-at-the-throne-of-his-glory | 2 Peter 2:6's Sodom-and-Gomorrah as the *ensample unto those that after should live ungodly* — the same judgment-pattern Mark 6 names.$n$,$n$2 Peter 2:6 — *And turning the cities of Sodom and Gomorrah into ashes condemned them with an overthrow, making them an ensample unto those that after should live ungodly;* *And whosoever shall not receive you, nor hear you, when you depart thence, shake off the dust under your feet for a testimony against them. Verily I say unto you, It shall be more tolerable for Sodom and Gomorrah in the day of judgment, than for that city.* (Mark 6:11) Peter treats Sodom and Gomorrah as a warning, *making them an ensample* for the ungodly who came after. The day of judgment Mark names already has its example burned to ashes. Peter then says Elohim (God) delivered just Lot out of it, so the righteous are taken out and the rest are judged.$n$,18,$n$2 Peter 2:6's Sodom-and-Gomorrah as the *ensample unto those that after should live ungodly* — the same judgment-pattern Mark 6 names.$n$,$n$2 Peter 2:6 — *making them an ensample unto those that after should live ungodly.* Sodom and Gomorrah stand as the warning example, with the righteous delivered from among them.$n$);
CREATE TEMP TABLE s503c_thread (id bigint, slug text, old_title text, new_title text, old_summary text, new_summary text) ON COMMIT DROP;
INSERT INTO s503c_thread VALUES (18, 'sheep-and-goats-judgment-of-the-nations-at-the-throne-of-his-glory', $n$The Sheep Divided From The Goats — The Gathered Sifted At The Throne Of His Glory$n$, $n$The Sheep Divided From The Goats — The Gathered Sifted At The Throne Of His Glory$n$, $n$*When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory: And before him shall be gathered all nations: and he shall separate them one from another, as a shepherd divideth his sheep from the goats: And he shall set the sheep on his right hand, but the goats on the left.* (Matthew 25:31-33). *All nations* names where the gathered come from. The seed was scattered among all the nations, and at his coming it is gathered out of them — and then sifted. Ezekiel saw the sifting and where it happens: *And I will bring you into the wilderness of the people, and there will I plead with you face to face... And I will cause you to pass under the rod, and I will bring you into the bond of the covenant: And I will purge out from among you the rebels, and them that transgress against me: I will bring them forth out of the country where they sojourn, and they shall not enter into the land of Yashar'el (Israel)* (Ezekiel 20:35, 37-38). The goats are parted from the sheep among the gathered, before the reign — not the nations judged for entry into it. The measure is mercy shown to *one of the least of these my brethren* (Matthew 25:40), and the brethren are the seed: *for which cause he is not ashamed to call them brethren* (Hebrews 2:11). The sheep *inherit the kingdom prepared for you from the foundation of the world* (Matthew 25:34) and enter the land as a kingdom of priests to the nations left alive (Zechariah 14:16); the goats are sent toward *everlasting fire, prepared for the devil and his angels* (Matthew 25:41). The warning was always given to the wheat.$n$, $n$*When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory: And before him shall be gathered all nations: and he shall separate them one from another, as a shepherd divideth his sheep from the goats: And he shall set the sheep on his right hand, but the goats on the left.* (Matthew 25:31-33). *All nations* names where the gathered come from. The seed was scattered among all the nations, and at his coming it is gathered out of them — and then sifted. Ezekiel saw the sifting and where it happens: *And I will bring you into the wilderness of the people, and there will I plead with you face to face... And I will cause you to pass under the rod, and I will bring you into the bond of the covenant: And I will purge out from among you the rebels, and them that transgress against me: I will bring them forth out of the country where they sojourn, and they shall not enter into the land of Yashar'el (Israel)* (Ezekiel 20:35, 37-38). The goats are parted from the sheep among the gathered, before the reign — not the nations judged for entry into it. The measure is mercy shown to *one of the least of these my brethren* (Matthew 25:40), and the brethren are the seed: *for which cause he is not ashamed to call them brethren* (Hebrews 2:11). The sheep *inherit the kingdom prepared for you from the foundation of the world* (Matthew 25:34) and enter the land as a kingdom of priests to the nations left alive (Zechariah 14:16); the goats are sent toward *everlasting fire, prepared for the devil and his angels* (Matthew 25:41). The warning was always given to the wheat.$n$);

DO $s503c$
DECLARE r record; x record; n int;
BEGIN
  FOR r IN SELECT * FROM s503c_cards LOOP
    SELECT xr.id, xr.note, sv.text AS stext, se.slug AS sed, sb.slug AS sbook, sc.chapter_number AS sch, sv.verse_number AS svn, te.slug AS ted, tb.slug AS tbook, tc.chapter_number AS tch, tv.verse_number AS tvn
      INTO x FROM cross_references xr
      JOIN verses sv ON sv.id = xr.source_verse_id JOIN chapters sc ON sc.id = sv.chapter_id JOIN books sb ON sb.id = sc.book_id JOIN editions se ON se.id = sb.edition_id
      JOIN verses tv ON tv.id = xr.target_verse_id JOIN chapters tc ON tc.id = tv.chapter_id JOIN books tb ON tb.id = tc.book_id JOIN editions te ON te.id = tb.edition_id
      WHERE xr.id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S503c: card % is gone', r.id; END IF;
    IF x.sed <> r.s_ed OR x.sbook <> r.s_book OR x.sch <> r.src_ch OR x.svn <> r.src_vn OR x.ted <> r.t_ed OR x.tbook <> r.tgt_book OR x.tch <> r.tgt_ch OR x.tvn <> r.tgt_vn THEN
      RAISE EXCEPTION 'S503c: card % no longer sits on the verse pair this was written for', r.id; END IF;
    IF x.stext <> r.src_text THEN RAISE EXCEPTION 'S503c: live text of % %:% differs from the read-back — re-dump and rebuild', r.s_book, r.src_ch, r.src_vn; END IF;
    IF x.note IS DISTINCT FROM r.old_note AND x.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S503c: the live note of card % differs from the read-back — re-dump and rebuild', r.id; END IF;
    SELECT count(*) INTO n FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id = r.thread_id AND (m.member_note IS NOT DISTINCT FROM r.old_mnote OR m.member_note IS NOT DISTINCT FROM r.new_mnote);
    IF n <> 1 THEN RAISE EXCEPTION 'S503c: card % has no member row in thread % carrying the member note this was written against', r.id, r.thread_id; END IF;
  END LOOP;
  SELECT t.* INTO x FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id AND s.slug = t.slug;
  IF NOT FOUND THEN RAISE EXCEPTION 'S503c: thread 18 not found under its slug'; END IF;
  SELECT count(*) INTO n FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id
    WHERE (t.title = s.old_title AND t.summary_md = s.old_summary) OR (t.title = s.new_title AND t.summary_md = s.new_summary);
  IF n <> 1 THEN RAISE EXCEPTION 'S503c: thread 18 title/summary differ from the read-back — re-dump and rebuild'; END IF;
END $s503c$;

DO $s503c2$
DECLARE n_notes int; n_m int; n_t int; n_c int;
BEGIN
  SELECT count(*) INTO n_c FROM s503c_cards;
  UPDATE cross_references xr SET note = c.new_note FROM s503c_cards c WHERE xr.id = c.id AND xr.note IS NOT DISTINCT FROM c.old_note AND c.old_note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_notes = ROW_COUNT;
  UPDATE cross_reference_thread_members m SET member_note = c.new_mnote FROM s503c_cards c WHERE m.cross_reference_id = c.id AND m.thread_id = c.thread_id AND m.member_note IS NOT DISTINCT FROM c.old_mnote AND c.old_mnote IS DISTINCT FROM c.new_mnote;
  GET DIAGNOSTICS n_m = ROW_COUNT;
  UPDATE cross_reference_threads t SET title = s.new_title, summary_md = s.new_summary FROM s503c_thread s WHERE t.id = s.id AND t.title = s.old_title AND t.summary_md = s.old_summary AND (s.old_title <> s.new_title OR s.old_summary <> s.new_summary);
  GET DIAGNOSTICS n_t = ROW_COUNT;
  RAISE NOTICE 'S503c (sheep-and-goats-judgment) summary: notes rewritten % / already there %; member notes rewritten % / already there %; thread rewritten % / already there %', n_notes, n_c - n_notes, n_m, n_c - n_m, n_t, 1 - n_t;
END $s503c2$;
COMMIT;
\echo 'session503c — sheep-and-goats-judgment done.'
